comp:
float anz = 3.0;
vec3 ret1, neu, blur;
vec2 uv3;




shader_body
{
vec2 pos = vec2 (sin(q10*3.14), cos(q10*3.14+q8*.04));
float r1 = fract(q10/2.0+time*0.2);
float r2 = fract(q10/4.0);
vec2 uv2;
float ang2, c, s;
uv -= .5;
uv *= aspect.xy;    
ret1 = vec3(((roam_sin.xy+0.5)/(0.01+length((uv)*r1-pos*0.07*q7))*0.015*q7).x);
ret1 += (roam_sin.xy+0.5).ggr/(0.01+length((uv)*r1+pos*0.07*q7))*0.015*q7;
ret1 += ((roam_cos.xy+0.5)/(0.02+8.0*pow(length(uv)-1.0*r1,2.0))*0.01*q7).x;
ret1*= (1.0+lum(ret1))/2.0;
float n = 1.0;
while (n <= anz) {
  ang2 = n/anz*3.1416;
  c = cos(ang2);
  s = sin(ang2);
  uv2.x =  uv.x*c - uv.y*s;
  uv2.y =  uv.x*s + uv.y*c;
  uv3= abs(fract(uv2*aspect.yx)-.5);
  neu =  max(texture(sampler_main, uv3).xyz,((texture(sampler_blur1, uv3).xyz * scale1) + bias1))/2.0 ;
  ret1 = max(ret1,neu+ret1);
n++;
}
ret = ret1*(1.0-rad);

